from __future__ import annotations

from dataclasses import dataclass
from pathlib import Path
from typing import Any, Protocol

from .content_package import SealedContentPackage, verify_sealed_content_package
from .domain import EffectState, OperationState, intent_digest
from .store import InvalidTransitionError, SQLiteProductStore


@dataclass(frozen=True)
class PublishObservation:
    state: str
    remote_video_id: str | None = None
    visibility: str | None = None
    evidence: dict[str, Any] | None = None

    @property
    def confirmed_private(self) -> bool:
        return (
            self.state == "MATCHED"
            and bool(self.remote_video_id)
            and str(self.visibility or "").upper() == "PRIVATE"
        )


@dataclass(frozen=True)
class ThumbnailObservation:
    persisted: bool
    token: str | None = None
    evidence: dict[str, Any] | None = None


class PublishAdapter(Protocol):
    def observe_private_upload(
        self,
        remote_channel_id: str,
        package: SealedContentPackage,
    ) -> PublishObservation: ...

    def dispatch_private_upload(
        self,
        remote_channel_id: str,
        package: SealedContentPackage,
    ) -> None: ...

    def observe_thumbnail(
        self,
        remote_channel_id: str,
        remote_video_id: str,
        package: SealedContentPackage,
    ) -> ThumbnailObservation: ...

    def dispatch_thumbnail(
        self,
        remote_channel_id: str,
        remote_video_id: str,
        package: SealedContentPackage,
    ) -> None: ...


@dataclass(frozen=True)
class PublishResult:
    status: str
    operation_id: str
    workspace_id: str
    remote_video_id: str | None
    next_action: str


@dataclass(frozen=True)
class PublishReview:
    workspace_id: str
    operation_id: str
    content_package_id: str
    remote_channel_id: str
    title: str
    visibility: str
    made_for_kids: bool
    asset_name: str
    asset_sha256: str
    thumbnail_name: str
    thumbnail_sha256: str
    package_digest: str
    review_digest: str


class PublishReviewService:
    """Read-only Owner review over one exact sealed Private publish intent."""

    def __init__(self, store: SQLiteProductStore):
        self.store = store

    def review(self, workspace_id: str) -> PublishReview:
        workspace = self.store.get_workspace(workspace_id)
        local_channel_id = workspace.get("youtube_channel_id")
        if not local_channel_id:
            raise InvalidTransitionError("exact YouTubeChannel must be bound before publish review")
        channel = self.store.get_youtube_channel(str(local_channel_id))
        remote_channel_id = str(channel["remote_channel_id"])

        active = self.store.get_active_operation(workspace_id)
        if active is None or active.kind != "PUBLISH_PRIVATE":
            raise InvalidTransitionError("active PUBLISH_PRIVATE operation is required for publish review")
        row = self.store.get_operation_content_package(active.operation_id)
        if row is None:
            raise InvalidTransitionError("seal one ContentPackage before publish review")
        package = verify_sealed_content_package(self.store, str(row["content_package_id"]))
        title = str(package.metadata.get("title") or "").strip()
        if not title:
            raise InvalidTransitionError("sealed ContentPackage title is required before publish review")
        visibility = str(
            package.metadata.get("visibility") or package.manifest.get("visibility_intent") or ""
        ).strip().upper()
        if visibility != "PRIVATE":
            raise InvalidTransitionError("publish review is restricted to PRIVATE visibility in V1")
        if not package.thumbnail_path or not package.thumbnail_sha256:
            raise InvalidTransitionError("current V1 publish requires a sealed custom thumbnail")

        snapshot = {
            "workspace_id": workspace_id,
            "operation_id": active.operation_id,
            "content_package_id": package.content_package_id,
            "remote_channel_id": remote_channel_id,
            "package_digest": package.package_digest,
            "asset_sha256": package.asset_sha256,
            "thumbnail_sha256": package.thumbnail_sha256,
            "visibility": visibility,
        }
        return PublishReview(
            workspace_id=workspace_id,
            operation_id=active.operation_id,
            content_package_id=package.content_package_id,
            remote_channel_id=remote_channel_id,
            title=title,
            visibility=visibility,
            made_for_kids=bool(package.metadata.get("made_for_kids")),
            asset_name=Path(package.asset_path).name,
            asset_sha256=package.asset_sha256,
            thumbnail_name=Path(package.thumbnail_path).name,
            thumbnail_sha256=package.thumbnail_sha256,
            package_digest=package.package_digest,
            review_digest=intent_digest(snapshot),
        )

    def approve(self, workspace_id: str, review_digest: str) -> PublishReview:
        approved = str(review_digest or "").strip()
        if not approved:
            raise InvalidTransitionError("Owner publish approval requires the exact review digest")
        current = self.review(workspace_id)
        if approved != current.review_digest:
            raise InvalidTransitionError("publish review changed; review the exact current intent again")
        return current


class PrivatePublishService:
    """Crash-safe Private upload orchestration with reconcile-before-retry semantics."""

    EFFECT_TYPE = "youtube.video.upload"
    THUMBNAIL_EFFECT_TYPE = "youtube.video.thumbnail"

    def __init__(self, store: SQLiteProductStore, adapter: PublishAdapter):
        self.store = store
        self.adapter = adapter

    def publish(
        self,
        workspace_id: str,
        content_package_id: str,
        *,
        expected_remote_channel_id: str | None = None,
        expected_package_digest: str | None = None,
    ) -> PublishResult:
        workspace = self.store.get_workspace(workspace_id)
        local_channel_id = workspace.get("youtube_channel_id")
        if not local_channel_id:
            raise InvalidTransitionError("exact YouTubeChannel must be bound before upload")
        channel = self.store.get_youtube_channel(str(local_channel_id))
        remote_channel_id = str(channel["remote_channel_id"])
        if expected_remote_channel_id is not None and remote_channel_id != expected_remote_channel_id:
            raise InvalidTransitionError("approved publish target channel changed before upload")

        package = verify_sealed_content_package(self.store, content_package_id)
        if expected_package_digest is not None and package.package_digest != expected_package_digest:
            raise InvalidTransitionError("approved sealed package changed before upload")
        if package.workspace_id != workspace_id:
            raise InvalidTransitionError("sealed ContentPackage belongs to another Workspace")
        if not package.thumbnail_path or not package.thumbnail_sha256:
            raise InvalidTransitionError(
                "legacy sealed package has no required custom thumbnail; cancel and reseal before publish"
            )

        operation = self.store.get_operation(package.operation_id)
        active = self.store.get_active_operation(workspace_id)
        if active is None or active.operation_id != operation.operation_id:
            raise InvalidTransitionError("sealed ContentPackage must belong to the active publish operation")
        if operation.kind != "PUBLISH_PRIVATE":
            raise InvalidTransitionError("sealed ContentPackage operation is not PUBLISH_PRIVATE")

        target = f"youtube-channel:{remote_channel_id}:package:{package.package_digest}"
        effect = next(
            (
                item
                for item in self.store.list_effects(operation.operation_id)
                if item.effect_type == self.EFFECT_TYPE and item.target_identity == target
            ),
            None,
        )

        observed = self.adapter.observe_private_upload(remote_channel_id, package)
        if effect is not None and effect.state == EffectState.SUCCEEDED.value:
            succeeded_remote_video_id = str(effect.remote_id or "").strip()
            if not succeeded_remote_video_id:
                raise InvalidTransitionError("succeeded upload effect is missing its exact remote video identity")
            if not observed.confirmed_private:
                return PublishResult(
                    "RECONCILE_REQUIRED",
                    operation.operation_id,
                    workspace_id,
                    succeeded_remote_video_id,
                    "re-observe the exact Private video before continuing thumbnail recovery",
                )
            if str(observed.remote_video_id) != succeeded_remote_video_id:
                return PublishResult(
                    "RECONCILE_REQUIRED",
                    operation.operation_id,
                    workspace_id,
                    succeeded_remote_video_id,
                    "observed video identity changed; reconcile the exact upload before thumbnail mutation",
                )
            return self._complete_thumbnail(
                operation_id=operation.operation_id,
                workspace_id=workspace_id,
                remote_channel_id=remote_channel_id,
                remote_video_id=succeeded_remote_video_id,
                package=package,
            )

        if observed.confirmed_private:
            if effect is None:
                effect = self.store.prepare_effect(
                    operation.operation_id,
                    self.EFFECT_TYPE,
                    target,
                    {
                        "package_digest": package.package_digest,
                        "asset_sha256": package.asset_sha256,
                        "visibility": "PRIVATE",
                    },
                )
            if effect.state == EffectState.PREPARING.value:
                self.store.mark_effect_observed_existing_succeeded(
                    effect.effect_id,
                    remote_id=str(observed.remote_video_id),
                    evidence=observed.evidence or {"observed_visibility": "PRIVATE"},
                )
            elif effect.state != EffectState.SUCCEEDED.value:
                self.store.mark_effect_succeeded(
                    effect.effect_id,
                    remote_id=observed.remote_video_id,
                    evidence=observed.evidence or {"observed_visibility": "PRIVATE"},
                )
            return self._complete_thumbnail(
                operation_id=operation.operation_id,
                workspace_id=workspace_id,
                remote_channel_id=remote_channel_id,
                remote_video_id=str(observed.remote_video_id),
                package=package,
            )

        if effect is None:
            effect = self.store.prepare_effect(
                operation.operation_id,
                self.EFFECT_TYPE,
                target,
                {
                    "package_digest": package.package_digest,
                    "asset_sha256": package.asset_sha256,
                    "visibility": "PRIVATE",
                },
            )

        if effect.state != EffectState.PREPARING.value:
            if effect.state != EffectState.RECONCILE_REQUIRED.value:
                effect = self.store.mark_effect_reconcile_required(
                    effect.effect_id,
                    evidence={"reason": "prior upload dispatch requires reconciliation"},
                )
            return PublishResult(
                "RECONCILE_REQUIRED",
                operation.operation_id,
                workspace_id,
                effect.remote_id,
                "reconcile actual YouTube upload; do not redispatch",
            )

        # Persist dispatch-uncertain lineage before crossing the external boundary.
        # The effect was read before the adapter observation. Another request may
        # have claimed it while that observation was in flight. The SQLite
        # transition is the dispatch claim: only the caller that atomically moves
        # PREPARING -> DISPATCHED may cross the provider boundary.
        try:
            self.store.mark_effect_dispatched(effect.effect_id)
        except InvalidTransitionError:
            current = self.store.get_effect(effect.effect_id)
            return PublishResult(
                "RECONCILE_REQUIRED",
                operation.operation_id,
                workspace_id,
                current.remote_id,
                "another request claimed this upload; reconcile the original effect",
            )
        try:
            self.adapter.dispatch_private_upload(remote_channel_id, package)
        except Exception:
            self.store.mark_effect_reconcile_required(
                effect.effect_id,
                evidence={"dispatch_exception": True},
            )
            return PublishResult(
                "RECONCILE_REQUIRED",
                operation.operation_id,
                workspace_id,
                None,
                "upload outcome unknown; reconcile before retry",
            )

        refreshed = self.adapter.observe_private_upload(remote_channel_id, package)
        if not refreshed.confirmed_private:
            self.store.mark_effect_reconcile_required(
                effect.effect_id,
                evidence=refreshed.evidence or {"reason": "post_dispatch_readback_not_confirmed"},
            )
            return PublishResult(
                "RECONCILE_REQUIRED",
                operation.operation_id,
                workspace_id,
                refreshed.remote_video_id,
                "reconcile actual YouTube upload; do not redispatch",
            )

        self.store.mark_effect_succeeded(
            effect.effect_id,
            remote_id=refreshed.remote_video_id,
            evidence=refreshed.evidence or {"observed_visibility": "PRIVATE"},
        )
        return self._complete_thumbnail(
            operation_id=operation.operation_id,
            workspace_id=workspace_id,
            remote_channel_id=remote_channel_id,
            remote_video_id=str(refreshed.remote_video_id),
            package=package,
        )

    def _complete_thumbnail(
        self,
        *,
        operation_id: str,
        workspace_id: str,
        remote_channel_id: str,
        remote_video_id: str,
        package: SealedContentPackage,
    ) -> PublishResult:
        assert package.thumbnail_path is not None
        assert package.thumbnail_sha256 is not None
        target = (
            f"youtube-video:{remote_video_id}:thumbnail:{package.thumbnail_sha256}"
        )
        prior = self.store.find_succeeded_effect(
            workspace_id,
            self.THUMBNAIL_EFFECT_TYPE,
            target,
        )
        current = next(
            (
                item
                for item in self.store.list_effects(operation_id)
                if item.effect_type == self.THUMBNAIL_EFFECT_TYPE
                and item.target_identity == target
            ),
            None,
        )
        observed = self.adapter.observe_thumbnail(
            remote_channel_id,
            remote_video_id,
            package,
        )

        if current is None:
            current = self.store.prepare_effect(
                operation_id,
                self.THUMBNAIL_EFFECT_TYPE,
                target,
                {
                    "remote_video_id": remote_video_id,
                    "thumbnail_sha256": package.thumbnail_sha256,
                    "pre_token": observed.token,
                },
            )

        if current.state == EffectState.SUCCEEDED.value:
            self.store.finish_operation(operation_id, OperationState.SUCCEEDED)
            return PublishResult(
                "SUCCEEDED",
                operation_id,
                workspace_id,
                remote_video_id,
                "review final Workspace state",
            )

        if (
            prior is not None
            and observed.persisted
            and observed.token
            and prior.evidence
            and prior.evidence.get("post_token") == observed.token
        ):
            self.store.mark_effect_observed_existing_succeeded(
                current.effect_id,
                remote_id=remote_video_id,
                evidence={
                    "post_token": observed.token,
                    "source": "prior-thumbnail-effect-and-fresh-editor-readback",
                },
            )
            self.store.finish_operation(operation_id, OperationState.SUCCEEDED)
            return PublishResult(
                "SUCCEEDED",
                operation_id,
                workspace_id,
                remote_video_id,
                "review final Workspace state",
            )

        pre_token = current.intent.get("pre_token")
        surface_ready = bool((observed.evidence or {}).get("surface_ready", True))
        if current.state != EffectState.PREPARING.value:
            if observed.persisted and observed.token and observed.token != pre_token:
                self.store.mark_effect_succeeded(
                    current.effect_id,
                    remote_id=remote_video_id,
                    evidence={
                        **(observed.evidence or {}),
                        "post_token": observed.token,
                        "reconciled_after_dispatch": True,
                    },
                )
                self.store.finish_operation(operation_id, OperationState.SUCCEEDED)
                return PublishResult(
                    "SUCCEEDED",
                    operation_id,
                    workspace_id,
                    remote_video_id,
                    "review final Workspace state",
                )
            if current.state != EffectState.RECONCILE_REQUIRED.value:
                self.store.mark_effect_reconcile_required(
                    current.effect_id,
                    evidence={"reason": "prior thumbnail dispatch requires reconciliation"},
                )
            return PublishResult(
                "RECONCILE_REQUIRED",
                operation_id,
                workspace_id,
                remote_video_id,
                "reconcile exact video thumbnail; do not redispatch",
            )

        if not surface_ready:
            return PublishResult(
                "RECONCILE_REQUIRED",
                operation_id,
                workspace_id,
                remote_video_id,
                "re-observe exact video editor before thumbnail dispatch",
            )

        # Claim the thumbnail effect atomically for the same reason as upload:
        # concurrent retries must not both act on a stale PREPARING snapshot.
        try:
            self.store.mark_effect_dispatched(current.effect_id)
        except InvalidTransitionError:
            latest = self.store.get_effect(current.effect_id)
            return PublishResult(
                "RECONCILE_REQUIRED",
                operation_id,
                workspace_id,
                remote_video_id,
                "another request claimed this thumbnail; reconcile the original effect",
            )
        try:
            self.adapter.dispatch_thumbnail(
                remote_channel_id,
                remote_video_id,
                package,
            )
        except Exception:
            self.store.mark_effect_reconcile_required(
                current.effect_id,
                evidence={"dispatch_exception": True},
            )
            return PublishResult(
                "RECONCILE_REQUIRED",
                operation_id,
                workspace_id,
                remote_video_id,
                "thumbnail outcome unknown; reconcile before retry",
            )

        refreshed = self.adapter.observe_thumbnail(
            remote_channel_id,
            remote_video_id,
            package,
        )
        if not (
            refreshed.persisted
            and refreshed.token
            and refreshed.token != pre_token
        ):
            self.store.mark_effect_reconcile_required(
                current.effect_id,
                evidence=refreshed.evidence
                or {"reason": "post_thumbnail_readback_not_confirmed"},
            )
            return PublishResult(
                "RECONCILE_REQUIRED",
                operation_id,
                workspace_id,
                remote_video_id,
                "reconcile exact video thumbnail; do not redispatch",
            )

        self.store.mark_effect_succeeded(
            current.effect_id,
            remote_id=remote_video_id,
            evidence={
                **(refreshed.evidence or {}),
                "post_token": refreshed.token,
            },
        )
        self.store.finish_operation(operation_id, OperationState.SUCCEEDED)
        return PublishResult(
            "SUCCEEDED",
            operation_id,
            workspace_id,
            remote_video_id,
            "review final Workspace state",
        )

    def _eligibility_service(self, workspace_id: str) -> EligibilityPhoneService:
        runner = self._runner_for_workspace(workspace_id)
        vault = DPAPIPhoneLeaseVault(self.data_root / "secrets" / "phone-leases")
        return EligibilityPhoneService(
            self.store,
            ViOTPProviderAdapter(),
            RawCDPPhoneUIAdapter(runner),
            vault,
        )

    def inspect_eligibility(self, workspace_id: str) -> dict[str, Any]:
        result = self._eligibility_service(workspace_id).inspect_required_eligibility(workspace_id)
        return {"result": asdict(result), "workspace": self.workspace_overview(workspace_id)}

    def ensure_eligibility(self, workspace_id: str) -> dict[str, Any]:
        result = self._eligibility_service(workspace_id).ensure_required_eligibility(workspace_id)
        return {"result": asdict(result), "workspace": self.workspace_overview(workspace_id)}

    def seal_content(self, workspace_id: str, package_path: str) -> dict[str, Any]:
        workspace = self.store.get_workspace(workspace_id)
        local_channel_id = workspace.get("youtube_channel_id")
        if not local_channel_id:
            raise InvalidTransitionError("exact channel binding is required before content intake")
        channel = self.store.get_youtube_channel(str(local_channel_id))
        eligibility = json.loads(channel["observed_eligibility_json"] or "{}")
        if eligibility.get("phone_verification_required") or not eligibility.get("custom_thumbnail_enabled"):
            raise InvalidTransitionError(
                "required YouTube eligibility must be reconciled before content intake"
            )
        active = self.store.get_active_operation(workspace_id)
        if active is None:
            operation = self.store.begin_operation(
                workspace_id,
                "PUBLISH_PRIVATE",
                {"visibility": "PRIVATE", "package_path": str(Path(package_path).resolve())},
            )
        else:
            operation = active
            if operation.kind != "PUBLISH_PRIVATE":
                raise InvalidTransitionError(f"Workspace is busy with {operation.kind}")
            if operation.intent.get("package_path") != str(Path(package_path).resolve()):
                raise InvalidTransitionError("active publish operation is bound to a different package")
        created_operation = active is None
        try:
            existing = self.store.get_operation_content_package(operation.operation_id)
            if existing:
                sealed_id = existing["content_package_id"]
            else:
                sealed = seal_content_package(
                    self.store,
                    workspace_id=workspace_id,
                    operation_id=operation.operation_id,
                    package_dir=package_path,
                )
                sealed_id = sealed.content_package_id
            review = PublishReviewService(self.store).review(workspace_id)
        except Exception:
            if (
                created_operation
                and self.store.get_operation_content_package(operation.operation_id) is None
                and not self.store.list_effects(operation.operation_id)
            ):
                self.store.finish_operation(operation.operation_id, "CANCELLED")
            raise
        return {
            "content_package_id": sealed_id,
            "operation_id": operation.operation_id,
            "publish_review": asdict(review),
            "workspace": self.workspace_overview(workspace_id),
        }

    def publish_review(self, workspace_id: str) -> dict[str, Any]:
        review = PublishReviewService(self.store).review(workspace_id)
        return {"publish_review": asdict(review), "workspace": self.workspace_overview(workspace_id)}

    def publish_private(self, workspace_id: str, review_digest: str) -> dict[str, Any]:
        review = PublishReviewService(self.store).approve(workspace_id, review_digest)
        runner = self._runner_for_workspace(workspace_id)
        result = PrivatePublishService(self.store, HybridPublishAdapter(runner)).publish(
            workspace_id,
            review.content_package_id,
            expected_remote_channel_id=review.remote_channel_id,
            expected_package_digest=review.package_digest,
        )
        return {"result": asdict(result), "workspace": self.workspace_overview(workspace_id)}

    def _cdp_url_for_workspace(self, workspace_id: str) -> str:
        workspace = self.store.get_workspace(workspace_id)
        profile_id = workspace.get("browser_profile_id")
        if not profile_id:
            raise InvalidTransitionError("Workspace BrowserProfile is not provisioned")
        profile = self.store.get_browser_profile(str(profile_id))
        runtime = self.youtube.observe_runtime(str(profile["gpm_profile_id"]))
        candidates = runtime.get("candidates") if isinstance(runtime, dict) else None
        candidate = candidates[0] if isinstance(candidates, list) and len(candidates) == 1 else None
        url = candidate.get("cdp_url") if isinstance(candidate, dict) else None
        if runtime.get("state") != "RUNNING_ATTACHABLE" or not isinstance(url, str):
            raise ControlCenterError("exact GPM browser runtime is not uniquely attachable")
        return url

    def _runner_for_workspace(
        self,
        workspace_id: str,
        *,
        script: str = "studio_runtime.mjs",
    ) -> NodeCDPRunner:
        port = cdp_port(self._cdp_url_for_workspace(workspace_id))
        if port is None:
            raise ControlCenterError("exact GPM browser runtime CDP port is unavailable")
        return NodeCDPRunner(port, script=script)

    @staticmethod
    def _next_action(workspace, account, channel, runtime, active) -> str:
        if workspace["archive_state"] != "ACTIVE":
            return "Workspace is archived"
        if active:
            if active.state == "NEEDS_OPERATOR" or workspace.get("health") == "NEEDS_OPERATOR":
                return "Owner action required in the visible browser"
            if active.state in {"RECONCILE_REQUIRED", "DISPATCHED", "CONFIRMING"}:
                return "Reconcile the current operation; do not retry blindly"
            return f"Continue {active.kind.lower().replace('_', ' ')}"
        if not account or not workspace.get("browser_profile_id"):
            return "Set up account, optional proxy and BrowserProfile"
        if runtime.get("state") == "GPM_UNAVAILABLE":
            return "Open/reconnect GPMLogin Local API, then reconcile the bound BrowserProfile"
        if runtime.get("state") != "RUNNING_ATTACHABLE":
            return "Start/reconcile the bound GPM BrowserProfile"
        desired = json.loads(workspace.get("desired_config_json") or "{}")
        if not channel and not desired.get("pack_id"):
            return "Select the desired Channel Pack before channel creation"
        if not channel:
            return "Authenticate and bind the exact YouTube channel"
        if not desired.get("pack_id"):
            return "Select the desired Channel Pack before channel configuration"
        eligibility = json.loads(channel["observed_eligibility_json"] or "{}")
        if not eligibility:
            return "Apply Channel Pack, then inspect feature eligibility"
        if eligibility.get("phone_verification_required"):
            return "Owner approval required before paid phone verification"
